#===============================================================================
# DesertCharSelect — character select carousel at game start
#===============================================================================
# pbDesertCharSelect opens a full-screen carousel of playable charsets (see
# playable.rb, generated by build_catalog.py). Left/Right cycle, the centre
# sprite walks in place, and confirming sets the player name + overworld
# charset. The choice is stored on PokemonGlobalMetadata so save/load keeps it.
#===============================================================================

module DesertCharSelect
  # nil = plain dark fill. Set to a Pictures/ filename (no extension) later.
  BACKGROUND_IMAGE = nil
  # nil = keep whatever BGM is already playing (map / intro music).
  BGM = nil
  VISIBLE = 5
  # Zoom / opacity by distance from the selected centre index.
  ZOOM_BY_DIST = { 0 => 3.0, 1 => 2.0, 2 => 1.5 }.freeze
  OPACITY_BY_DIST = { 0 => 255, 1 => 180, 2 => 120 }.freeze
  FRAME_DELAY = 8
  FRAMES_PER_DIR = 4
  DIRS = 4

  #-----------------------------------------------------------------------------
  # Scene
  #-----------------------------------------------------------------------------
  class Scene
    def initialize
      @index = rand(PLAYABLE.length)
      @frame = 0
      @frame_timer = 0
      @sprites = {}
      @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
      @viewport.z = 99999
      @chosen = nil
    end

    def run
      pbBGMPlay(BGM) if BGM && !BGM.empty?
      create_sprites
      refresh
      loop do
        Graphics.update
        Input.update
        update_animation
        if Input.repeat?(Input::LEFT)
          @index = (@index - 1) % PLAYABLE.length
          @frame = 0
          @frame_timer = 0
          refresh
          pbSEPlay("GUI sel cursor") if defined?(pbSEPlay)
        elsif Input.repeat?(Input::RIGHT)
          @index = (@index + 1) % PLAYABLE.length
          @frame = 0
          @frame_timer = 0
          refresh
          pbSEPlay("GUI sel cursor") if defined?(pbSEPlay)
        elsif Input.trigger?(Input::USE)
          entry = PLAYABLE[@index]
          name = _INTL(entry[:name_key])
          if pbConfirmMessage(_INTL("MSG_CHARSEL_CONFIRM", name))
            @chosen = entry
            break
          end
          # Rebuild overlay / sprites after the confirm message closes.
          refresh
        end
        # BACK is ignored — selection is required.
      end
      dispose
      return @chosen
    end

    def create_sprites
      @sprites["bg"] = Sprite.new(@viewport)
      if BACKGROUND_IMAGE && !BACKGROUND_IMAGE.empty? &&
         pbResolveBitmap("Graphics/Pictures/#{BACKGROUND_IMAGE}")
        @sprites["bg"].bitmap = Bitmap.new("Graphics/Pictures/#{BACKGROUND_IMAGE}")
      else
        bmp = Bitmap.new(Graphics.width, Graphics.height)
        bmp.fill_rect(0, 0, Graphics.width, Graphics.height, Color.new(20, 16, 14))
        @sprites["bg"].bitmap = bmp
      end
      @sprites["bg"].z = 0

      VISIBLE.times do |slot|
        spr = Sprite.new(@viewport)
        spr.ox = 0
        spr.oy = 0
        spr.z = 10 + slot
        @sprites["char_#{slot}"] = spr
      end

      if pbResolveBitmap("Graphics/UI/left_arrow")
        @sprites["left"] = Sprite.new(@viewport)
        @sprites["left"].bitmap = Bitmap.new("Graphics/UI/left_arrow")
        @sprites["left"].x = 16
        @sprites["left"].y = Graphics.height / 2 - @sprites["left"].bitmap.height / 2
        @sprites["left"].z = 30
      end
      if pbResolveBitmap("Graphics/UI/right_arrow")
        @sprites["right"] = Sprite.new(@viewport)
        @sprites["right"].bitmap = Bitmap.new("Graphics/UI/right_arrow")
        @sprites["right"].x = Graphics.width - 16 - @sprites["right"].bitmap.width
        @sprites["right"].y = Graphics.height / 2 - @sprites["right"].bitmap.height / 2
        @sprites["right"].z = 30
      end

      @sprites["overlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
      @sprites["overlay"].z = 40
    end

    def update_animation
      @frame_timer += 1
      if @frame_timer >= FRAME_DELAY
        @frame_timer = 0
        @frame = (@frame + 1) % FRAMES_PER_DIR
        refresh_centre_frame
      end
    end

    def refresh
      half = VISIBLE / 2
      spacing = Graphics.width / (VISIBLE + 1)
      centre_y = Graphics.height / 2 - 24
      VISIBLE.times do |slot|
        offset = slot - half
        idx = (@index + offset) % PLAYABLE.length
        entry = PLAYABLE[idx]
        spr = @sprites["char_#{slot}"]
        bmp = RPG::Cache.character(entry[:charset], 0)
        spr.bitmap = bmp
        cw = bmp.width / FRAMES_PER_DIR
        ch = bmp.height / DIRS
        frame = (offset == 0) ? @frame : 0
        spr.src_rect.set(frame * cw, 0, cw, ch)
        dist = offset.abs
        zoom = ZOOM_BY_DIST[dist] || 1.0
        spr.zoom_x = zoom
        spr.zoom_y = zoom
        spr.opacity = OPACITY_BY_DIST[dist] || 100
        spr.ox = cw / 2
        spr.oy = ch / 2
        spr.x = spacing * (slot + 1)
        spr.y = centre_y
        spr.z = 10 + (half - dist)
      end
      draw_overlay
    end

    def refresh_centre_frame
      half = VISIBLE / 2
      spr = @sprites["char_#{half}"]
      return if !spr || !spr.bitmap || spr.bitmap.disposed?
      cw = spr.bitmap.width / FRAMES_PER_DIR
      ch = spr.bitmap.height / DIRS
      spr.src_rect.set(@frame * cw, 0, cw, ch)
    end

    def draw_overlay
      overlay = @sprites["overlay"].bitmap
      overlay.clear
      base = Color.new(248, 240, 224)
      shadow = Color.new(40, 32, 24)
      title = _INTL("UI_CHARSEL_TITLE")
      entry = PLAYABLE[@index]
      name = _INTL(entry[:name_key])
      counter = "#{@index + 1}/#{PLAYABLE.length}"
      textpos = [
        [title, Graphics.width / 2, 28, 2, base, shadow],
        [name, Graphics.width / 2, Graphics.height - 72, 2, base, shadow],
        [counter, Graphics.width / 2, Graphics.height - 40, 2, base, shadow]
      ]
      pbDrawTextPositions(overlay, textpos)
    end

    def dispose
      pbDisposeSpriteHash(@sprites) if defined?(pbDisposeSpriteHash)
      if @sprites
        @sprites.each_value do |spr|
          next if !spr || (spr.respond_to?(:disposed?) && spr.disposed?)
          spr.dispose if spr.respond_to?(:dispose)
        end
      end
      @viewport.dispose if @viewport
      @sprites = {}
    end
  end

  #-----------------------------------------------------------------------------
  # Apply a chosen entry to the player
  #-----------------------------------------------------------------------------
  def self.apply!(entry)
    raise "No character selected" if !entry
    if defined?($player) && $player && $player.character_ID != 1
      pbChangePlayer(1)
    end
    if defined?($PokemonGlobal) && $PokemonGlobal
      $PokemonGlobal.desert_player_charset = entry[:charset]
    end
    name = _INTL(entry[:name_key])
    pbTrainerName(name)
    if defined?($game_player) && $game_player
      $game_player.charsetData = nil if $game_player.respond_to?(:charsetData=)
      if $game_player.respond_to?(:refresh_charset)
        $game_player.refresh_charset
      elsif defined?(pbUpdateVehicle)
        pbUpdateVehicle
      end
    end
    return entry
  end
end

class PokemonGlobalMetadata
  attr_accessor :desert_player_charset
end

#===============================================================================
# pbGetPlayerCharset alias — swap walk/run for the chosen Desert Town charset
#===============================================================================
if defined?(pbGetPlayerCharset)
  alias desert_char_select_pbGetPlayerCharset pbGetPlayerCharset

  def pbGetPlayerCharset(*args)
    charset = args[0]
    trainer = args[1]
    if $PokemonGlobal && $PokemonGlobal.desert_player_charset && charset.is_a?(String)
      begin
        trainer_obj = trainer || (defined?($player) ? $player : nil)
        cid = trainer_obj && trainer_obj.respond_to?(:character_ID) ? trainer_obj.character_ID : 1
        meta = GameData::PlayerMetadata.get(cid || 1)
        if meta
          walk = meta.walk_charset
          run = meta.run_charset
          run = walk if !run || run == ""
          if charset == walk || charset == run
            args = args.dup
            args[0] = $PokemonGlobal.desert_player_charset
          end
        end
      rescue StandardError
        # Fall through to the original if metadata is unavailable mid-boot.
      end
    end
    return desert_char_select_pbGetPlayerCharset(*args)
  end
end

#===============================================================================
# Entry point
#===============================================================================
def pbDesertCharSelect
  chosen = nil
  pbFadeOutIn {
    scene = DesertCharSelect::Scene.new
    chosen = scene.run
  }
  return DesertCharSelect.apply!(chosen) if chosen
  return nil
end
